INSERT INTO _fleet_sync_leases(database,holder,epoch,expires_at,last_renewed_at) VALUES(?1,json_extract(?2,'$.holder'),NULLIF(?2 -> '$.epoch','null'),json_extract(?2,'$.expires_at'),json_extract(?2,'$.last_renewed_at')) ON CONFLICT(database) DO UPDATE SET holder=excluded.holder,epoch=excluded.epoch,expires_at=excluded.expires_at,last_renewed_at=excluded.last_renewed_at,updated_at=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER))
